def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if not isinstance(nanoseconds, int):
            raise ValueError("nanoseconds must be an integer")

        if tz is not None and not isinstance(tz, str):
            raise ValueError("tz must be a string or None")

        from datetime import datetime, timezone, timedelta

        # Assuming nanoseconds since midnight
        seconds, nanos = divmod(nanoseconds, 1_000_000_000)
        minutes, seconds = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)

        if tz is None:
            # Create a naive time object
            return datetime.strptime(f"{hours:02}:{minutes:02}:{seconds:02}.{nanos:09}", "%H:%M:%S.%f").time()
        else:
            # Create a timezone-aware time object
            tzinfo = timezone(timedelta(hours=int(tz)))
            dt = datetime.strptime(f"{hours:02}:{minutes:02}:{seconds:02}.{nanos:09}", "%H:%M:%S.%f").replace(tzinfo=tzinfo)
            return dt.time()
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

