def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    try:
        if not isinstance(name, str) or not name:
            raise ValueError("Name must be a non-empty string.")
        if not isinstance(fields, dict):
            raise ValueError("Fields must be a dictionary.")
        if not isinstance(srid_map, dict):
            raise ValueError("SRID map must be a dictionary.")

        class Point:
            def __init__(self, **kwargs):
                for field, field_type in fields.items():
                    if field not in kwargs:
                        raise ValueError(f"Missing required field: {field}")
                    if not isinstance(kwargs[field], field_type):
                        raise TypeError(f"Field {field} must be of type {field_type.__name__}")
                    setattr(self, field, kwargs[field])
                self.srid_map = srid_map

            def __repr__(self):
                field_values = ', '.join(f"{field}={getattr(self, field)!r}" for field in fields)
                return f"{name}({field_values})"

        Point.__name__ = name
        return Point

    except Exception as e:
        print(f"An error occurred: {e}")
        return None

