def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    try:
        if not orderings:
            return []

        # Create a graph to represent the orderings
        graph = {}
        for ordering in orderings:
            for i in range(len(ordering) - 1):
                if ordering[i] not in graph:
                    graph[ordering[i]] = []
                if ordering[i + 1] not in graph[ordering[i]]:
                    graph[ordering[i]].append(ordering[i + 1])

        # Perform a topological sort on the graph
        visited = set()
        result = []

        def dfs(node):
            if node in visited:
                return
            visited.add(node)
            if node in graph:
                for neighbor in graph[node]:
                    dfs(neighbor)
            result.append(node)

        # Find all nodes with no incoming edges
        all_nodes = set()
        for ordering in orderings:
            all_nodes.update(ordering)
        nodes_with_no_incoming_edges = all_nodes - set(j for i in graph for j in graph[i])

        # Start DFS from nodes with no incoming edges
        for node in nodes_with_no_incoming_edges:
            dfs(node)

        # Reverse the result to get the correct order
        result.reverse()

        return result

    except Exception as e:
        print(f"An error occurred: {e}")
        return []

