        if not app or not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Invalid application object or missing manifest")

        default_schema = {}
        for resource in app.spec.manifest:
            if resource.get('kind') and resource.get('apiVersion'):
                resource_key = f"{resource['apiVersion']}/{resource['kind']}"
                if resource_key not in app.spec.observer_schema:
                    default_schema[resource_key] = {
                        "metrics": ["cpu_usage", "memory_usage"],
                        "conditions": ["Ready"]
                    }
        return default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

