def _extract_number_and_supplment_from_issue_element(issue):
    try:
        issue = issue.strip().lower()
        number = None
        suppl = None

        # Check for number
        if issue.isdigit():
            number = issue
        else:
            import re
            number_match = re.search(r'^(\d+-?\d*)', issue)
            if number_match:
                number = number_match.group(1)

        # Check for suppl
        suppl_keywords = ['suppl', 'spe', 's', 'pr', 'sp', '.']
        if any(keyword in issue for keyword in suppl_keywords):
            suppl = 'suppl'
            if 'spe' in issue or 's' in issue or 'sp' in issue:
                suppl = 'spe'
            if 'pr' in issue:
                suppl += ' pr'
            suppl_match = re.search(r'(\d+-?\d*)', issue.split(suppl)[1])
            if suppl_match:
                suppl += ' ' + suppl_match.group(1)

        return number, suppl
    except Exception as e:
        return None, None

