def fromutc(self, dt):
    try:
        if dt.tzinfo is None:
            raise ValueError("The provided datetime object must be timezone-aware.")

        # Convert the datetime to UTC
        dt_utc = dt.astimezone(datetime.timezone.utc)

        # Convert the UTC datetime to the target timezone
        dt_target = self.normalize(dt_utc.astimezone(self))

        # Check for fold state
        if dt_target.fold:
            # If the datetime is in a fold state, it means it's the second occurrence
            # of the ambiguous datetime. We need to adjust it to the first occurrence.
            dt_target = dt_target.replace(fold=0)

        return dt_target
    except Exception as e:
        raise ValueError(f"An error occurred while converting the datetime: {e}")

