def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Try parsing as XML (XRD)
            root = ET.fromstring(document)
            xrd = {}
            for element in root:
                if element.tag.endswith('}Subject'):
                    xrd['subject'] = element.text
                elif element.tag.endswith('}Alias'):
                    xrd.setdefault('aliases', []).append(element.text)
                elif element.tag.endswith('}Link'):
                    link = {}
                    for attr, value in element.attrib.items():
                        link[attr] = value
                    xrd.setdefault('links', []).append(link)
            return xrd
        except ET.ParseError:
            raise ValueError("Document is neither valid JSON nor valid XRD XML")
    except Exception as e:
        raise ValueError(f"An error occurred while parsing the document: {e}")

